    /* Caché visuellement mais toujours accessible au clavier et aux lecteurs d'écran */
    input[type="checkbox"] {
      position: absolute;
      opacity: 0;
      width: 1px;
      height: 1px;
    }

    input[type="checkbox"]:focus-visible + .slider {
