    }

    .slider::before {
      content: '';
      position: absolute;
      left: 2px;
      top: 2px;
      width: 16px;
      height: 16px;
      background: #fff;
      border-radius: 50%;
      transition: transform 0.3s;
    }

    input[type="checkbox"]:checked+.slider {
      background: #222;
    }

    input[type="checkbox"]:checked+.slider::before {
      transform: translateX(20px);
      background: #f357a8;
    }

