import { TestBed } from '@angular/core/testing';
import { FooterComponent } from './footer.component';

describe('FooterComponent', () => {
  beforeEach(async () => {
    localStorage.removeItem('theme');
    await TestBed.configureTestingModule({ imports: [FooterComponent] }).compileComponents();
  });

  afterEach(() => {
    localStorage.removeItem('theme');
    document.body.classList.remove('dark-theme', 'white-theme');
  });

  function toggle(checked: boolean) {
    const fixture = TestBed.createComponent(FooterComponent);
    fixture.detectChanges();
    const input = (fixture.nativeElement as HTMLElement).querySelector('input[type="checkbox"]') as HTMLInputElement;
    input.checked = checked;
    input.dispatchEvent(new Event('change'));
    fixture.detectChanges();
    return fixture;
  }

  it('passe en thème sombre et mémorise le choix', () => {
    const fixture = toggle(true);

    expect(document.body.classList).toContain('dark-theme');
    expect(document.body.classList).not.toContain('white-theme');
    expect(localStorage.getItem('theme')).toBe('dark');
    expect((fixture.nativeElement as HTMLElement).textContent).toContain('Thème Sombre');
  });

  it('repasse en thème clair et mémorise le choix', () => {
    toggle(false);

    expect(document.body.classList).toContain('white-theme');
    expect(document.body.classList).not.toContain('dark-theme');
    expect(localStorage.getItem('theme')).toBe('white');
  });

  it('réapplique le thème mémorisé au chargement', () => {
    localStorage.setItem('theme', 'dark');
    const fixture = TestBed.createComponent(FooterComponent);

    expect(fixture.componentInstance.isDark).toBeTrue();
    expect(document.body.classList).toContain('dark-theme');
  });

  it('affiche l\'année en cours', () => {
    const fixture = TestBed.createComponent(FooterComponent);
    fixture.detectChanges();

    expect((fixture.nativeElement as HTMLElement).textContent).toContain(`© ${new Date().getFullYear()}`);
  });
});

import { Component } from '@angular/core';

@Component({
  selector: 'app-footer',
  templateUrl: './footer.component.html',
  styleUrl: './footer.component.scss'
})
export class FooterComponent {
  isDark = false;
  currentYear = new Date().getFullYear();

  constructor() {
    if (typeof window !== 'undefined' && typeof localStorage !== 'undefined') {
      const saved = localStorage.getItem('theme');
      this.isDark = saved === 'dark' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    this.applyTheme();
  }

  toggleTheme(event: Event) {
    this.isDark = (event.target as HTMLInputElement).checked;
    if (typeof window !== 'undefined' && typeof localStorage !== 'undefined') {
      localStorage.setItem('theme', this.isDark ? 'dark' : 'white');
    }
    this.applyTheme();
  }

  applyTheme() {
    if (typeof document !== 'undefined') {
      document.body.classList.toggle('dark-theme', this.isDark);
      document.body.classList.toggle('white-theme', !this.isDark);
    }
  }
}

:host {
  display: block;
  position: sticky;
  top: 0;
  z-index: 1000;
  background: linear-gradient(45deg, #30135f 0%, #792a53 50%, #30135f 100%);
  color: white;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

/* Même largeur et mêmes marges que le contenu des pages */
.container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0.9rem clamp(1rem, 4vw, 2rem);
}

.logo {
  font-family: Roboto, sans-serif;
  font-weight: bold;
  font-size: 1.5rem;
  letter-spacing: 1px;
  white-space: nowrap;
}

.nav {
  display: flex;
  flex-wrap: nowrap;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-link {
  position: relative;
  padding: 0.4rem 0.75rem;
  color: white;
  text-decoration: none;
  white-space: nowrap;

  /* Soulignement animé au survol */
  &::after {
    content: '';
    position: absolute;
    left: 0.75rem;
    right: 0.75rem;
    bottom: 0;
    height: 2px;
    background: white;
    transform: scaleX(0);
    transition: transform 0.25s ease;
  }

  &:hover,
  &:focus-visible {
    color: rgba(255, 255, 255, 0.85);
  }

  &:hover::after,
  &.a-active::after {
    transform: scaleX(1);
  }
}

.a-active {
  color: white !important;
  font-weight: 600;
}

/* Mobile : nom sur une ligne, liens sur une seule ligne en dessous */
@media (max-width: 767.98px) {
  .container {
    flex-direction: column;
    gap: 0.4rem;
    padding-top: 0.6rem;
    padding-bottom: 0.4rem;
  }

  .logo {
    font-size: 1.25rem;
  }

  .nav {
    gap: 0;
    justify-content: center;
  }

  .nav-link {
    padding: 0.4rem 0.6rem;
    font-size: 0.95rem;

    &::after {
      left: 0.6rem;
      right: 0.6rem;
    }
  }
}

