/** Projet tel que renvoyé par GET /api/projects (carte de la page « Mes projets »). */
export interface Project {
  id: number;
  name: string;
  /** Description courte, affichée sur la carte. */
  description: string;
  technologies: string[];
}

/**
 * Détail d'un projet, affiché dans la fenêtre du projet.
 * Contrat prévu pour GET /api/projects/{id} (voir docs/api-project-details.md).
 */
export interface ProjectDetails extends Project {
  /** Description longue : paragraphes séparés par une ligne vide, lignes « - » pour les listes. */
  longDescription: string;
  /** Aperçus de l'application, générés à l'avance. */
  images: ProjectImage[];
  /** Arborescence des fichiers sources. */
  files: ProjectFileNode[];
  /** Lien de téléchargement de l'archive .zip, renseigné seulement si le projet l'autorise explicitement. */
  zipUrl?: string | null;
  /** Lien vers le dépôt public, s'il existe. */
  repoUrl?: string | null;
}

export interface ProjectImage {
  url: string;
  alt: string;
  caption?: string;
}

export interface ProjectFileNode {
  name: string;
  /** Chemin depuis la racine du projet, séparé par « / ». */
  path: string;
  type: 'file' | 'directory';
  /** Taille en octets (fichiers). */
  size?: number;
  /** Contenu texte du fichier ; absent pour les fichiers binaires ou trop volumineux. */
  content?: string | null;
  /** URL du fichier brut (images, binaires). */
  url?: string | null;
  children?: ProjectFileNode[];
}

@if (tree.length) {
	<div class="file-browser">
		<nav class="tree" aria-label="Fichiers du projet">
			<ul role="tree">
				<ng-container *ngTemplateOutlet="nodes; context: { $implicit: tree, depth: 0 }"></ng-container>
			</ul>
		</nav>

		<section class="viewer" aria-live="polite">
			@if (selected) {
				<header class="viewer-header">
					<span class="breadcrumb-path">
						@for (part of breadcrumb; track $index; let last = $last) {
							@if (last) {
								<strong>{{ part }}</strong>
							} @else {
								<span>{{ part }}</span><span class="sep">/</span>
							}
						}
					</span>
					<span class="meta">
						@if (selected.content) {
							{{ lines.length }} lignes ·
						}
						{{ formatSize(selected.size) }}
					</span>
				</header>
				@if (selected.content) {
					<div class="code">
						<table>
							<tbody>
								@for (line of lines; track $index) {
									<tr>
										<td class="line-number">{{ $index + 1 }}</td>
										<td class="line"><pre>{{ line }}</pre></td>
									</tr>
								}
							</tbody>
						</table>
					</div>
				} @else if (isImage(selected)) {
					<div class="image-preview"><img [src]="selected.url" [alt]="selected.name" loading="lazy" /></div>
				} @else {
					<p class="empty"><i class="bi bi-eye-slash" aria-hidden="true"></i> Aperçu non disponible pour ce fichier.</p>
				}
			} @else {
				<p class="empty"><i class="bi bi-hand-index" aria-hidden="true"></i> Sélectionnez un fichier pour afficher son contenu.</p>
			}
		</section>
	</div>
} @else {
	<p class="no-files"><i class="bi bi-folder-x" aria-hidden="true"></i> Les fichiers de ce projet ne sont pas encore disponibles.</p>
}

<ng-template #nodes let-list let-depth="depth">
	@for (node of list; track node.path) {
		<li role="treeitem" [attr.aria-expanded]="node.type === 'directory' ? expanded.has(node.path) : null"
			[attr.aria-selected]="node === selected">
			<button type="button" class="node" [class.active]="node === selected" [style.padding-left.rem]="0.5 + depth * 1"
				(click)="toggle(node)">
				@if (node.type === 'directory') {
					<i class="bi chevron" [class.bi-chevron-down]="expanded.has(node.path)" [class.bi-chevron-right]="!expanded.has(node.path)" aria-hidden="true"></i>
				} @else {
					<span class="chevron"></span>
				}
				<i class="bi {{ icon(node) }}" [class.folder]="node.type === 'directory'" aria-hidden="true"></i>
				<span class="name">{{ node.name }}</span>
			</button>
			@if (node.type === 'directory' && expanded.has(node.path)) {
				<ul role="group">
					<ng-container *ngTemplateOutlet="nodes; context: { $implicit: node.children ?? [], depth: depth + 1 }"></ng-container>
				</ul>
			}
		</li>
	}
</ng-template>

